import {registry,newThread,start,step,pause,cancel,restore,requestExport,approve,consumeExport,markdown,compress,SAMPLE_TIME} from './engine.js?v=1.0.1';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={threads:[],memories:[],active:null};try{state={...state,...JSON.parse(localStorage.getItem('xbuddy-v1')||'{}')}}catch{}
state.threads.forEach(t=>{if(t.status==='running'){t.status='paused';t.tasks.forEach(x=>{if(x.status==='running')x.status='pending'});t.traces.forEach(x=>{if(x.status==='running'){x.status='aborted';x.error='刷新中断，结果未提交'}})}if(t.approval?.status==='pending'){t.approval.status='expired';t.status='completed'}});
let tab='plan',view='workspace',scenario='normal',busy=false,limits={calls:12,cost:.12,seconds:120},draft='';
const statuses={pending:'待执行',running:'运行中',paused:'已暂停',completed:'已完成',cancelled:'已取消',failed:'失败',degraded:'降级完成',awaiting_approval:'等待审批'};
function current(){return state.threads.find(t=>t.id===state.active)}
function save(){try{localStorage.setItem('xbuddy-v1',JSON.stringify(state))}catch{toast('本地存储空间不足，请删除旧线程后重试')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function modal(title,body){$('#detail').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button data-action="close" aria-label="关闭详情">×</button></div>${body}`;$('#detail').showModal()}
function json(x){return `<pre>${esc(JSON.stringify(x,null,2))}</pre>`}
function download(name,text,type='text/markdown'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function render(){let t=current();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span>✳</span>投资 X Buddy<small>YOUR RESEARCH COMPANION</small></div><button class="new" data-action="new">＋ 新建研究</button><div><div class="section-label">研究线程 · ${state.threads.length}</div><div class="threads">${state.threads.length?state.threads.map(x=>`<div class="thread ${x.id===state.active?'active':''}"><button data-action="thread" data-id="${x.id}" title="${esc(x.goal)}">◌ &nbsp;${esc(x.goal)}</button><button class="delete" data-action="delete" data-id="${x.id}" aria-label="删除研究 ${esc(x.goal)}">×</button></div>`).join(''):'<div class="small">从一个值得研究的问题开始</div>'}</div></div><div class="navlinks"><button data-action="nav" data-view="workspace">▦ &nbsp; 研究工作台</button><button data-action="nav" data-view="tools">⌘ &nbsp; 能力与工具</button><button data-action="nav" data-view="memory">◇ &nbsp; 长期记忆 <span class="tag">${state.memories.length}</span></button><button data-action="about">ⓘ &nbsp; 使用与边界</button></div><footer><div>一个目标，一条可验证的研究路径。</div><div class="connection"><span class="dot"></span>DEMO 引擎就绪<br>扶摇 / iFinD · 未连接</div><br>个人研究空间 · v1.0<br>仅保存在当前浏览器</footer></aside><main class="main"><div class="topline"><span>个人空间 &nbsp; / &nbsp; ${view==='tools'?'能力注册表':view==='memory'?'长期记忆':'研究工作台'}</span><span class="tag demo">DEMO · 合成数据</span></div>${view==='tools'?toolsView():view==='memory'?memoryView():t?threadView(t):home()}</main><aside class="observer">${observer(t)}</aside></div>`;bind();}
function home(){return `<div class="eyebrow">RESEARCH WITH A CLEAR TRACE</div><h1>把研究目标，变成可靠的证据。</h1><p class="subtitle">你的个人投资研究 Agent。每一步可见，每个判断可追溯。</p><div class="composer"><textarea id="goal" aria-label="研究目标" placeholder="你想研究什么？例如：比较沪深300与中证1000的估值和市场宽度">${esc(draft)}</textarea><div class="composer-bottom"><span class="small"><span class="dot"></span>DEMO 规则规划器 &nbsp; · &nbsp; 无真实模型调用</span><button class="primary" data-action="create">开始研究 &nbsp; ↗</button></div></div><div class="examples">${['比较沪深300与中证1000的估值和市场宽度','研究半导体行业的风险变量','检查创业板的流动性与估值证据'].map((x,i)=>`<button data-action="example" data-i="${i}">${x} ↗</button>`).join('')}</div><div class="row"><h2>研究有章法，过程有把握</h2><span class="small">AGENT HARNESS</span></div><div class="intro-grid"><div class="intro-card"><span class="number">01</span><b>先计划，再执行</b><p>拆解问题，注册工具，在预算和权限范围内逐步完成。</p></div><div class="intro-card"><span class="number">02</span><b>证据先于结论</b><p>原始字段、时点与口径完整保留，明确区分事实与推断。</p></div><div class="intro-card"><span class="number">03</span><b>随时停，接着做</b><p>检查点、压缩摘要与长期记忆，让研究持续且可恢复。</p></div></div><div class="banner">当前为可操作的 DEMO 研究环境：数据由确定性公式生成，样本日期固定为 2026-10-20（UTC+8），并非实时行情。研究引擎不输出买卖、仓位建议或涨跌预测。</div><button class="link" data-action="nav" data-view="tools">查看工具能力、权限与数据接入边界 →</button>`}
function threadView(t){let approved=t.approval?.status==='pending';return `<div class="eyebrow">RESEARCH THREAD · ${t.id.slice(0,8).toUpperCase()}</div><h1 style="font-size:25px">${esc(t.goal)}</h1><div class="row"><span class="small">${new Date(t.createdAt).toLocaleString('zh-CN')} · ${t.symbols.map(esc).join(' / ')} · 仅本浏览器</span><span class="tag ${t.status==='cancelled'?'bad':''}">${statuses[t.status]}</span></div>${t.warning?`<div class="banner">${esc(t.warning)}</div>`:''}<div class="panel"><div class="row"><div><h3>${t.status==='awaiting_approval'?'研究完成，等待导出审批':t.status==='completed'?'研究完成，证据已归档':t.status==='cancelled'?'研究已停止':t.status==='running'?'正在逐步建立证据链':'研究计划已准备'}</h3><span class="small">${t.cursor} / ${t.tasks.length} 项已处理 · ${t.evidence.length} 条证据</span></div><div class="controls">${t.status==='running'?'<button data-action="pause">Ⅱ 暂停</button>':!['completed','cancelled','awaiting_approval'].includes(t.status)?'<button class="primary" data-action="run">▶ '+(t.cursor?'继续执行':'执行计划')+'</button>':''}${!['completed','cancelled','awaiting_approval'].includes(t.status)?'<button class="danger" data-action="cancel">取消</button>':''}</div></div><div class="progress"><i style="width:${t.cursor/5*100}%"></i></div></div>${approved?`<div class="approval"><h3>需要你的确认 · 本地报告导出</h3><p>范围：当前线程 Markdown 报告，包含目标与全部证据。目的：保存研究成果。文件仅下载到本机，无网络外发；本次授权不可复用。</p><div class="controls"><button class="primary" data-action="approve">批准并下载</button><button data-action="reject">拒绝</button></div></div>`:''}<div class="tabs">${[['plan','执行计划'],['evidence','证据库'],['report','研究产物'],['trace','调用追踪']].map(([id,label])=>`<button class="${tab===id?'selected':''}" data-action="tab" data-tab="${id}">${label}${id==='evidence'?` · ${t.evidence.length}`:''}</button>`).join('')}</div>${tab==='plan'?`<div class="panel">${t.tasks.map((x,i)=>`<div class="task ${x.status}"><span class="task-icon">${x.status==='completed'?'✓':x.status==='running'?'◌':i+1}</span><div class="task-title">${x.name}<small>${x.id} · ${i===4?'基于证据编制研究成果':'DEMO 合成数据 / 只读'}</small></div><span class="task-status">${statuses[x.status]}${x.attempts?' · '+x.attempts+'次':''}</span></div>`).join('')}</div><div class="small">计划引擎：确定性规则规划器。读取的长期记忆 ${t.memories.length} 条。不同目标提取不同标的；未识别时默认比较沪深300与中证1000。</div>`:tab==='evidence'?evidenceView(t):tab==='report'?reportView(t):traceView(t)}`}
function evidenceView(t){return t.evidence.length?`<div class="banner">以下均为合成样本；点击证据编号查看字段、公式、口径与调用记录。</div><div style="overflow:auto"><table class="evidence"><thead><tr><th>证据 / 来源</th><th>标的</th><th>指标</th><th>原始值</th><th>质量</th></tr></thead><tbody>${t.evidence.map(e=>`<tr><td><button class="link" data-action="evidence" data-id="${e.id}">${e.id} ↗</button><div class="small">DEMO</div></td><td>${e.symbol}</td><td>${e.label}</td><td>${e.value===null?'—':e.value} ${e.unit}</td><td><span class="tag ${e.quality==='valid'?'':'bad'}">${e.quality==='valid'?'合成有效':e.quality==='missing'?'缺失':'过期'}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><div class="empty-icon">⌕</div>执行计划后，证据会逐项出现。<br><span class="small">缺失或失败将显式保留，不会被填成正常数据。</span></div>'}
function reportView(t){let r=t.report;if(!r)return '<div class="empty"><div class="empty-icon">▤</div>研究产物尚未生成<br><span class="small">完成取数与质量检查后，生成可追溯报告。</span></div>';return `<div class="panel report"><div class="row"><span class="tag">研究备忘录 · DEMO</span><span class="small">规则置信分 ${r.confidence}/100</span></div><p class="small">生成 ${esc(r.time)}<br>数据时点 ${SAMPLE_TIME} · 分数为完整性规则评估，非统计概率。</p><h2>${esc(r.title)}</h2><h3>01 &nbsp; 合成样本事实</h3>${r.facts.length?r.facts.map(f=>`<div class="fact">${esc(f.text)} ${f.ids.map(id=>`<button class="link" data-action="evidence" data-id="${id}">[${id}]</button>`).join('')}</div>`).join(''):'<p>没有可用的合成样本事实。</p>'}<h3>02 &nbsp; 归纳 · 仅限演示样本</h3><p>${esc(r.inference)}</p><h3>03 &nbsp; 不确定判断与限制</h3><div class="uncertain">${r.unknown.map(esc).join('<br>')}</div><h3>04 &nbsp; 重新评估的条件</h3><ul>${r.conditions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="small">研究读取的记忆：${r.memory.map(esc).join('；')||'无'}。所有判断仅演示工作流，不构成投资建议。</p><div class="controls"><button class="primary" data-action="export">申请导出 Markdown</button><button data-action="json">查看完整运行 JSON</button></div></div><h3>沿着证据，继续研究</h3><div class="examples">${['风格轮动','行业风险','流动性变量'].map(x=>`<button data-action="follow" data-sub="${x}">${x} ↗</button>`).join('')}</div>`}
function traceView(t){return t.traces.length?t.traces.map(x=>`<details class="trace"><summary><span class="tag ${['error','timeout'].includes(x.status)?'bad':''}">${esc(x.status)}</span> &nbsp;${x.id} · ${x.tool}<span class="small"> · ${x.duration??'…'} ms · 第${x.attempt}次</span></summary>${json(x)}</details>`).join(''):'<div class="empty">尚无工具调用。计划执行时将记录真实的本地耗时。</div>'}
function toolsView(){return `<div class="eyebrow">CAPABILITY REGISTRY</div><h1>能力与工具</h1><p class="subtitle">每次调用都有边界，每项输出都有来源。</p><div class="banner">金融接口未授权；下列只读工具运行于浏览器本地，使用 DEMO 合成数据。扶摇 / iFinD 适配器未实现，不会发起真实请求。</div>${registry.map(x=>`<details class="panel"><summary><b>${x.name}</b> &nbsp;<span class="tag">${x.permission==='read'?'只读':'本地计算'}</span> <span class="small">${x.id} · DEMO</span></summary>${json(x)}</details>`).join('')}<div class="panel"><h3>local_report_export <span class="tag demo">人工审批</span></h3><p class="small">仅当前报告本地下载；批准后单次消耗授权。无外发服务。交易与账户写入能力未注册。</p></div>`}
function memoryView(){return `<div class="eyebrow">LONG-TERM CONTEXT</div><h1>长期记忆</h1><p class="subtitle">记录研究偏好，为后续线程提供持续上下文。</p><div class="composer"><textarea id="memory-input" aria-label="记忆内容" placeholder="例如：优先检查数据完整性，使用三年估值分位。"></textarea><div class="row"><span class="small">新线程将读取记忆快照；不含账户或持仓信息。</span><button class="primary" data-action="add-memory">保存记忆</button></div></div>${state.memories.length?state.memories.map(m=>`<div class="memory"><span>◇</span><p>${esc(m.text)}<br><span class="small">${esc(m.at)}</span></p><button class="link" data-action="edit-memory" data-id="${m.id}">编辑</button><button class="link danger" data-action="delete-memory" data-id="${m.id}">删除</button></div>`).join(''):'<div class="empty">还没有记忆。添加一条研究偏好，下一次研究即可读取。</div>'}`}
function observer(t){let n=t?t.context.join('').length:0;return `<div><div class="row"><h2>◉ &nbsp; 运行观察器</h2><span class="tag">LOCAL</span></div><div class="metric-grid"><div class="metric"><strong>${t?t.traces.length:0}<span class="small"> / ${t?t.limits.calls:limits.calls}</span></strong><small>工具调用</small></div><div class="metric"><strong>¥${t?t.cost.toFixed(3):'0.000'}</strong><small>模拟成本，非实际费用</small></div><div class="metric"><strong>${t?(t.elapsed/1000).toFixed(1):'0.0'}<span class="small"> s</span></strong><small>累计本地执行耗时</small></div><div class="metric"><strong>${t?t.tokens:0}</strong><small>模拟 token 估算</small></div></div><div class="panel"><h3>上下文窗口</h3><div class="observe-row"><span>${n} 字符</span><span>阈值 500 字符</span></div><div class="bar"><i style="width:${Math.min(100,n/5)}%"></i></div><p class="small">超过阈值自动生成结构摘要；证据原文始终保留。</p><button class="link" data-action="context">${t?.summary?'查看压缩摘要 ↗':'查看上下文 ↗'}</button></div><div class="panel"><div class="row"><h3>检查点与恢复</h3><span class="small">${t?t.checkpoints.length:0} 个</span></div>${t?.checkpoints.length?`<select id="checkpoint" aria-label="选择检查点">${t.checkpoints.map((c,i)=>`<option value="${i}">${c.id} · 完成 ${c.cursor} / 5 项</option>`).reverse().join('')}</select><button style="margin-top:10px;width:100%;font-size:11px" data-action="restore" ${t.status==='running'?'disabled':''}>从所选检查点恢复</button>`:'<p class="small">执行前及每个任务完成后，保存完整状态快照。</p>'}</div></div><div><div class="panel"><h3>实验室 <span class="tag demo">DEMO</span></h3><label for="scenario">新研究的故障场景</label><select id="scenario">${[['normal','正常执行'],['transient','工具首次失败 · 自动重试'],['persistent','工具持续失败 · 降级'],['missing','市场宽度数据缺失'],['stale','行情数据过期'],['model','规划器失败 · 规则降级']].map(([id,l])=>`<option value="${id}" ${scenario===id?'selected':''}>${l}</option>`).join('')}</select><p class="small">配置仅作用于下一条研究，运行中不切换。</p><label>新研究停止预算</label><div class="budget">${[['calls','调用',1,30,1],['cost','¥ 模拟',.001,1,.001],['seconds','秒',1,600,1]].map(([id,l,min,max,step])=>`<label>${l}<input id="limit-${id}" aria-label="${l}预算" type="number" min="${min}" max="${max}" step="${step}" value="${limits[id]}"></label>`).join('')}</div><p class="small">次数 / 模拟成本 / 本地执行时长任一触顶即暂停。提高预算需新建研究。</p></div><h3 style="margin-top:24px">运行事件</h3><div class="timeline">${t?.events.length?t.events.slice(-6).reverse().map(x=>`<div><time>${new Date(x.at).toLocaleTimeString('zh-CN')}</time>${esc(x.message)}</div>`).join(''):'<div><time>READY</time>等待研究目标<br>引擎、权限和追踪已就绪。</div>'}</div></div>`}
async function loop(t){if(busy)return;busy=true;try{while(t.status==='running'){await step(t);save();render();}}catch(e){t.status='failed';t.events.push({at:new Date().toISOString(),message:'未预期错误：'+e.message});toast(e.message)}finally{busy=false;save();render();}}
function make(goal){try{const t=newThread(goal,scenario,limits,state.memories);state.threads.unshift(t);state.active=t.id;view='workspace';tab='plan';draft='';save();render()}catch(e){toast(e.message)}}
function bind(){ $('#goal')?.addEventListener('input',e=>draft=e.target.value);$('#scenario')?.addEventListener('change',e=>scenario=e.target.value);for(let key of ['calls','cost','seconds'])$('#limit-'+key)?.addEventListener('change',e=>{let v=+e.target.value;if(!Number.isFinite(v)||v<+e.target.min||v>+e.target.max){e.target.value=limits[key];toast('请输入预算允许范围内的数值');return}limits[key]=v;});}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,t=current();try{switch(a){case 'close':$('#detail').close();return;case 'new':state.active=null;view='workspace';break;case 'thread':state.active=b.dataset.id;view='workspace';tab='plan';break;case 'delete':{let x=state.threads.find(t=>t.id===b.dataset.id);cancel(x);state.threads=state.threads.filter(t=>t.id!==x.id);if(state.active===x.id)state.active=null;break}case 'nav':view=b.dataset.view;break;case 'create':make($('#goal').value);return;case 'example':draft=['比较沪深300与中证1000的估值和市场宽度','研究半导体行业的风险变量','检查创业板的流动性与估值证据'][b.dataset.i];render();$('#goal').focus();return;case 'run':if(busy){toast('上一次调用正在安全结束，请稍后继续');return}if(start(t)){save();render();loop(t)}return;case 'pause':pause(t);break;case 'cancel':cancel(t);break;case 'tab':tab=b.dataset.tab;break;case 'evidence':{let ev=t.evidence.find(x=>x.id===b.dataset.id);modal('证据 '+ev.id+' · 原始字段与口径',`<span class="tag demo">DEMO 合成数据</span>${json(ev)}<button data-action="call" data-id="${ev.callId}">查看对应调用 ${ev.callId}</button>`);return}case 'call':{let trace=t.traces.find(x=>x.id===b.dataset.id);$('#detail').innerHTML=`<div class="dialog-head"><h2>调用追踪 ${esc(b.dataset.id)}</h2><button data-action="close">关闭</button></div>${json(trace)}`;return}case 'context':modal('上下文与结构摘要',t?json({summary:t.summary,context:t.context,memory_snapshot:t.memories,evidence_retained:t.evidence.map(x=>x.id)}):'<p>尚未建立研究上下文。</p>');return;case 'restore':restore(t,t.checkpoints[+$('#checkpoint').value]);tab='plan';break;case 'export':requestExport(t);break;case 'approve':if(approve(t,true)&&consumeExport(t)){download('XBuddy-DEMO-'+t.id.slice(0,8)+'.md',markdown(t));toast('本次授权已消耗，报告已下载')}break;case 'reject':approve(t,false);toast('已拒绝，未生成文件');break;case 'json':modal('运行记录 · 可复制 JSON',json(t));return;case 'follow':{const parent=t.id;make(`围绕${t.symbols.join('与')}继续研究${b.dataset.sub}；关联目标：${t.goal}`);current().parentId=parent;save();return}case 'add-memory':{const text=$('#memory-input').value.trim();if(!text){toast('请先填写记忆');return}state.memories.push({id:crypto.randomUUID(),text,at:new Date().toISOString()});break}case 'delete-memory':state.memories=state.memories.filter(m=>m.id!==b.dataset.id);break;case 'edit-memory':{const m=state.memories.find(x=>x.id===b.dataset.id);modal('编辑长期记忆',`<textarea id="edit-text" aria-label="编辑记忆">${esc(m.text)}</textarea><button class="primary" data-action="save-memory" data-id="${m.id}">保存修改</button>`);return}case 'save-memory':{const text=$('#edit-text').value.trim();if(!text){toast('记忆不能为空');return}Object.assign(state.memories.find(x=>x.id===b.dataset.id),{text,at:new Date().toISOString()});$('#detail').close();break}case 'about':modal('使用与产品边界',`<p>这是题目13的独立应用。输入研究目标，查看计划后执行；在右侧实验室切换故障和预算，然后新建研究。支持暂停、取消、检查点恢复、证据溯源和审批导出。</p><p>当前没有金融数据授权，所有数值均为 DEMO 合成数据；规划和报告由可审计规则生成，没有真实 LLM 调用。成本和 token 为模拟估算，执行耗时为浏览器本地测量。</p><p>存储仅在本浏览器 localStorage，无云同步、真实外发、交易、账户访问或定时任务。真实扶摇 / iFinD 与 LLM 适配器未实现。请勿在目标和记忆中输入隐私或密钥。</p><p>合规关键词防线是演示层，报告模板不提供买卖建议。不是完整的生产金融合规系统。</p>`);return;}save();render();}catch(err){toast(err.message)}});
save();render();
